      + 'and habitat". Tarkistettu 6.9.2026.',
    kuva: 'elain-pak',
    // Piste on Chitralin vuoristossa Pohjois-Pakistanissa, 107,3
    // lautayksikköä Kabulista (vähimmäisetäisyys 35).
    lon: 72.0,
    lat: 35.9,
